  if(state.searchScope&&state.searchScope!=="all")p.set("scope",String(state.searchScope));
  if(state.searchDays)p.set("days",String(state.searchDays));
  if(state.unreadOnly)p.set("unread","1");
  if(state.attachmentOnly)p.set("attachment","1");
